from pathlib import Path
import json,csv
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch
R=Path(__file__).resolve().parents[1];F=R/'figures';F.mkdir(exist_ok=True)
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False,'axes.labelcolor':'#17343e','text.color':'#17343e','axes.titleweight':'bold','savefig.facecolor':'white'})
blue='#1c6070';teal='#378b80';orange='#b3693b';gray='#73878d'
def save(fig,name):
 fig.savefig(F/(name+'.png'),dpi=220,bbox_inches='tight');fig.savefig(F/(name+'.svg'),bbox_inches='tight');plt.close(fig)
def box(ax,x,y,w,h,text,color=blue):
 p=FancyBboxPatch((x,y),w,h,boxstyle='round,pad=0.012,rounding_size=0.008',facecolor='white',edgecolor=color,linewidth=1.5);ax.add_patch(p);ax.text(x+w/2,y+h/2,text,ha='center',va='center',fontsize=11);return p
def arrow(ax,a,b):ax.annotate('',xy=b,xytext=a,arrowprops=dict(arrowstyle='->',lw=1.5,color=gray))
fig,ax=plt.subplots(figsize=(10,2.5));ax.axis('off');ax.set(xlim=(-.03,1.03),ylim=(-.025,1.025))
box(ax,.02,.34,.19,.35,'Query set\n1 / 2 / 3 / 5 games');box(ax,.33,.34,.23,.35,'Learned game\nrepresentations');box(ax,.69,.61,.27,.24,'600 reference players\n10 games per player');box(ax,.69,.18,.27,.24,'Ranked player IDs\nReturn the top five');arrow(ax,(.21,.51),(.33,.51));arrow(ax,(.56,.51),(.69,.3));arrow(ax,(.825,.61),(.825,.42));ax.text(.02,.04,'New-family retrieval setting; schematic, not an example of labeled test answers.',fontsize=9,color=gray);save(fig,'retrieval_task')
d=json.loads((R/'results/data_summary.json').read_text())['player_game_histogram'];fig,ax=plt.subplots(figsize=(8,2.8));bars=ax.bar(d['labels'],d['counts'],color=blue,width=.65);ax.bar_label(bars,padding=3,fontsize=10);ax.set(xlabel='Training games per player',ylabel='Number of players',ylim=(0,1900));ax.text(.98,.95,'1,000,000 games · 8,007 players',ha='right',va='top',transform=ax.transAxes,fontsize=10);save(fig,'data_distribution')
fig,ax=plt.subplots(figsize=(10,3.3));ax.axis('off');ax.set(xlim=(-.03,1.03),ylim=(-.025,1.025));box(ax,.01,.38,.15,.25,'SGF records\n+ target colour');box(ax,.25,.68,.30,.22,'Coordinate Transformer\nplayer embeddings');box(ax,.25,.29,.30,.22,'HumanSL board features\n432 residual channels');box(ax,.65,.68,.30,.22,'Reference prototypes\nsequence fusion');box(ax,.65,.29,.30,.22,'MLP cosine + regularized\nLDA Gaussian score');box(ax,.42,.01,.34,.17,'Global score fusion → Top-5 IDs',teal)
arrow(ax,(.16,.55),(.25,.78));arrow(ax,(.16,.44),(.25,.4));arrow(ax,(.55,.79),(.65,.79));arrow(ax,(.55,.4),(.65,.4));ax.plot([.95,.985,.985],[.79,.79,.095],color=gray,lw=1.5);arrow(ax,(.985,.095),(.76,.095));arrow(ax,(.8,.29),(.65,.18));save(fig,'method_pipeline')
fig,ax=plt.subplots(figsize=(10,2.5));ax.axis('off');ax.set(xlim=(-.03,1.03),ylim=(-.025,1.025));box(ax,.01,.5,.27,.35,'Metric training\n1,000 → 6,000 players');box(ax,.38,.5,.25,.35,'Fixed holdout\n800 excluded players');box(ax,.72,.68,.26,.24,'600 sampled players\n15 games each');box(ax,.72,.34,.26,.24,'300 development rows\n300 audit rows',teal);box(ax,.16,.02,.63,.22,'Official evaluation: 800 public queries + 800 private queries',orange);arrow(ax,(.63,.68),(.72,.79));arrow(ax,(.85,.68),(.85,.58));ax.text(.01,.40,'Training / holdout identities are disjoint.',fontsize=10);ax.text(.01,.30,'Audit identities were reused in prior work.',fontsize=10,color=orange);save(fig,'validation_protocol')
rows=list(csv.DictReader((R/'results/submissions.csv').open()));sel=[x for x in rows if x['day_jst']=='2026-11-22'];vals=[float(x['public_score']) for x in sel];labels=['Raw replay','Lower MLP','Lower Gaussian','LM4 fusion','LM6 fusion'];fig,ax=plt.subplots(figsize=(9,3));bars=ax.bar(labels,vals,color=[gray,gray,gray,teal,blue]);ax.bar_label(bars,labels=[f'{x:.6f}' for x in vals],padding=3,fontsize=10);ax.axhline(.8674659,color=orange,linestyle='--',lw=1,label='Previous best 0.867466');ax.set(ylim=(.86,.872),ylabel='Public score');ax.legend(loc='upper left',frameon=False,fontsize=9);ax.text(.01,-.25,'Truncated vertical axis; scores are ranking utilities, not classification accuracies.',transform=ax.transAxes,fontsize=9);save(fig,'public_ablations')
fig,ax=plt.subplots(figsize=(8.5,2.7));labels=['verQ','No verifier','Learned policy','+ Gaussian','+ LM4'];v=[.8588357,.8630397,.8666413,.8674659,.8686865];ax.plot(labels,v,'o-',color=blue,lw=2);[ax.annotate(f'{y:.6f}',(i,y),xytext=(0,9),textcoords='offset points',ha='center',fontsize=9) for i,y in enumerate(v)];ax.set(ylabel='Best public score',ylim=(.855,.873));ax.text(.01,-.25,'Selected development milestones, not a controlled single-component ablation.',transform=ax.transAxes,fontsize=9);save(fig,'score_history')
x=json.loads((R/'results/expanded_validation.json').read_text());k=['1','2','3','5'];a=[x['audit_baseline_by_k'][i] for i in k];b=[x['audit_selected_by_k'][i] for i in k];fig,ax=plt.subplots(figsize=(8.5,3));xx=np.arange(4);ax.bar(xx-.18,a,.34,label='Six-encoder / policy proxy',color=gray);ax.bar(xx+.18,b,.34,label='+ 6,000-player metric',color=teal);ax.set(xticks=xx,xticklabels=k,xlabel='Query games',ylabel='Audit retrieval score',ylim=(.4,.98));ax.legend(loc='upper left',frameon=False,fontsize=9);[ax.text(i,max(a[i],b[i])+.012,f'+{b[i]-a[i]:.4f}',ha='center',fontsize=10) for i in range(4)];save(fig,'expanded_audit')
fig,ax=plt.subplots(figsize=(8.5,3));pts=[('Cosine',.01221478,.8649376-.8666413),('Gaussian',.01490197,.8665537-.8666413),('Trunk only',.014149,.8652248-.8666413),('Feature statistics',.01139218,.8583048-.8666413)];ax.axhline(0,color=gray,lw=1);ax.scatter([p[1] for p in pts],[p[2] for p in pts],color=blue,s=45)
for n,x,y in pts:ax.annotate(n,(x,y),xytext=(5,5),textcoords='offset points',fontsize=9)
ax.set(xlabel='Local audit gain',ylabel='Public-score change',xlim=(.0105,.0162),ylim=(-.0095,.0015));ax.text(.01,-.28,'Four Nov21 comparisons share a fixed learned-policy baseline; no causal fit is estimated.',transform=ax.transAxes,fontsize=9);save(fig,'local_public_gap')
